{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Ergotamine tartrate absolute oral bioavailability was less than 1% in patients after a 2 mg oral dose compared with intravenous AUC, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Tetrabenazine mean oral systemic availability was 0.049 ± 0.032 in seven patients, well below the 20% threshold and supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Commercial danazol capsules showed 30% oral bioavailability in humans, which is above the 20% threshold and argues against a uniformly low prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-assay-transfer evidence reports absolute oral bioavailability below 20%, often below 10%; one danazol record reaches 30% but is formulation- and food-dependent. No record directly tests rifampin co-treatment, so confidence is moderate.",
  "evidence_gaps": [
    "No supplied record measures the query under rifampin co-treatment.",
    "Molecule 10 has mixed results depending on formulation and fed/fasted state.",
    "Some records are qualitative or unspecified bioavailability type rather than numeric absolute F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

